// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * A setting read back from the watch. Enum-like values stay raw codes
 * (the app maps the ones it knows).
 */

public enum SettingValue: Equatable, Hashable {
    
    case timeSurface(dateFormat: UInt8, time12h: Bool
    )
    case signaling(antiloss: UInt8, call: UInt8, missedCall: UInt8, sms: UInt8, social: UInt8, email: UInt8, calendar: UInt8, inactivity: UInt8, lowPower: UInt8
    )
    case doNotDisturb(enabled: Bool, start: ClockTime, end: ClockTime
    )
    case analogMode(code: UInt8
    )
    case activityTracking(enabled: Bool
    )
    case screenTime(seconds: UInt16
    )
    case wrist(code: UInt8
    )
    case heartRateInterval(minutes: UInt8
    )
    case inactivity(enabled: Bool, days: UInt8, thresholdMin: UInt8, start: ClockTime, end: ClockTime
    )
    case caloriesType(code: UInt8
    )
    case displayOnMovement(enabled: Bool
    )
    case notificationSwitches(calls: Bool, missedCalls: Bool, sms: Bool, social: Bool, email: Bool, calendar: Bool
    )
    /**
     * 0x90 mask bits 2-3 : suivi sommeil manuel / auto-sleep.
     */
    case sleepSwitches(tracking: Bool, autoSleep: Bool
    )
    /**
     * Fenêtre auto-sleep lue sur 0x58.
     */
    case autoSleepWindow(enter: ClockTime, exit: ClockTime, days: UInt8
    )
    /**
     * Réglage simple sur un octet (unités, volume, luminosité, rappel,
     * taille du texte) — la valeur brute est renvoyée, l'app la mappe.
     */
    case byte(value: UInt8
    )
    case raw(payload: Data
    )





}

