// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * A decoded frame received from the watch.
 */

public enum WatchFrame: Equatable, Hashable {
    
    case battery(level: UInt8
    )
    /**
     * Return-code ack for a previous command (status 0 = OK, 1 = NOK).
     */
    case ack(cmd: UInt8, status: UInt8
    )
    /**
     * Watch-initiated event (0x8004): music controls and call reject.
     */
    case action(action: WatchAction
    )
    /**
     * The watch wants the phone's music state; `source` = the player picked
     * on the watch's music screen (0=Apple Music, 1=Spotify, 2=Deezer).
     */
    case musicStateRequest(source: UInt8
    )
    /**
     * Unrecognized music-control code.
     */
    case unknownMusic(code: UInt8
    )
    /**
     * 0xE2 — real-time heart-rate push from the watch `[bpm:1]`.
     */
    case realTimeHeartRate(bpm: UInt8
    )
    /**
     * Any other well-formed frame.
     */
    case other(cmd: UInt8, kind: UInt8, payload: Data
    )





}

#if compiler(>=6)
extension WatchFrame: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeWatchFrame: FfiConverterRustBuffer {
    typealias SwiftType = WatchFrame

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> WatchFrame {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .battery(level: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 2: return .ack(cmd: try FfiConverterUInt8.read(from: &buf), status: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 3: return .action(action: try FfiConverterTypeWatchAction.read(from: &buf)
        )
        
        case 4: return .musicStateRequest(source: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 5: return .unknownMusic(code: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 6: return .realTimeHeartRate(bpm: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 7: return .other(cmd: try FfiConverterUInt8.read(from: &buf), kind: try FfiConverterUInt8.read(from: &buf), payload: try FfiConverterData.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: WatchFrame, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .battery(level):
            writeInt(&buf, Int32(1))
            FfiConverterUInt8.write(level, into: &buf)
            
        
        case let .ack(cmd,status):
            writeInt(&buf, Int32(2))
            FfiConverterUInt8.write(cmd, into: &buf)
            FfiConverterUInt8.write(status, into: &buf)
            
        
        case let .action(action):
            writeInt(&buf, Int32(3))
            FfiConverterTypeWatchAction.write(action, into: &buf)
            
        
        case let .musicStateRequest(source):
            writeInt(&buf, Int32(4))
            FfiConverterUInt8.write(source, into: &buf)
            
        
        case let .unknownMusic(code):
            writeInt(&buf, Int32(5))
            FfiConverterUInt8.write(code, into: &buf)
            
        
        case let .realTimeHeartRate(bpm):
            writeInt(&buf, Int32(6))
            FfiConverterUInt8.write(bpm, into: &buf)
            
        
        case let .other(cmd,kind,payload):
            writeInt(&buf, Int32(7))
            FfiConverterUInt8.write(cmd, into: &buf)
            FfiConverterUInt8.write(kind, into: &buf)
            FfiConverterData.write(payload, into: &buf)
            
        }
    }
}


